/** 将字符串转换为数字，无法转换时返回 0。 */
export const toNumber = (value: string): number => {
  const normalized = value.replace(/[^0-9.-]/gi, "");
  const num = Number(normalized);
  return Number.isFinite(num) ? num : 0;
};

export { formatNumber } from "./formation";

/**
 * 计算数字数组的中位数。
 *
 * 排序时复制数组，避免修改调用方传入的原始数组。
 */
export const median = (arr: number[]): number => {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  if (sorted.length === 0) {
    return 0;
  }
  return sorted.length % 2 !== 0
    ? (sorted[mid] ?? 0)
    : ((sorted[mid - 1] ?? 0) + (sorted[mid] ?? 0)) / 2;
};

/** 为数字字符串添加千分位分隔符。 */
export const applyThousandSeparator = (
  value: string,
  thousandSeparator: boolean | string = ","
): string => {
  if (thousandSeparator === false) {
    return value;
  }
  const reg = /\B(?=(\d{3})+(?!\d))/g;
  if (thousandSeparator === true) {
    return value.replace(reg, ",");
  }
  return value.replace(reg, thousandSeparator);
};

/**
 * 四舍五入并保留指定的小数位数。
 *
 * 返回数字而不是字符串，适合继续参与计算。
 */
export const toRoundFixed = (num: number, scale: number): number => {
  if (!Number.isFinite(num) || !Number.isFinite(scale) || scale < 0) {
    return num;
  }
  const factor = 10 ** Math.floor(scale);
  return Math.round((num + Number.EPSILON) * factor) / factor;
};

/** 将字符串解析为浮点数，无法解析时返回 0。 */
export const parseNumber = (val: string): number => {
  const value = parseFloat(val);
  return Number.isNaN(value) ? 0 : value;
};

/** 判断值是否为有限数字或合法的数字字符串。 */
export function isRealNumber(v: unknown): v is number {
  if (typeof v === "number") {
    return Number.isFinite(v);
  }
  if (typeof v === "string") {
    const num = parseFloat(v);
    return !Number.isNaN(num) && /^-?\d*\.?\d+$/.test(v);
  }
  return false;
}

/** 判断数字是否位于指定区间内，区间端点顺序不影响结果。 */
export function isBetween(value: number, start: number, end: number): boolean {
  const min = Math.min(start, end);
  const max = Math.max(start, end);

  return value >= min && value <= max;
}

/** 将百分比数字四舍五入到两位小数并添加百分号。 */
export const formatPercentage = (num?: number): string => {
  if (isRealNumber(num)) {
    return `${toRoundFixed(num, 2)}%`;
  }
  return "0%";
};

/** 向上取整并保留指定的小数位数。 */
export function roundUpToNDecimalPlaces(
  value: number,
  decimals: number
): number {
  if (!Number.isFinite(value) || !Number.isFinite(decimals) || decimals < 0) {
    return value;
  }
  const factor = 10 ** decimals;
  return Math.ceil(value * factor) / factor;
}

/**
 * 将比例转换为百分比并调整舍入误差，使结果总和为 100。
 *
 * 调整会作用于返回的新数组，不会修改输入数组。
 */
export function adjustRatiosToSum100(values: number[]): number[] {
  // 先计算原始比例
  const ratios = values.map((v) => v * 100);

  // 四舍五入到两位小数
  const rounded = ratios.map((r) => Math.round(r * 100) / 100);

  // 计算差值
  const sum = rounded.reduce((a, b) => a + b, 0);
  const diff = 100 - sum;

  if (Math.abs(diff) < 0.01) return rounded;

  // 找出舍入误差最大的项进行调整
  const errors = ratios
    .map((r, i) => ({
      index: i,
      error: r - (rounded[i] ?? 0),
    }))
    .sort((a, b) => Math.abs(b.error) - Math.abs(a.error));

  // 分配差值到误差最大的项
  const firstError = errors[0];
  if (!firstError) {
    return rounded;
  }
  rounded[firstError.index] =
    Math.round(((rounded[firstError.index] ?? 0) + diff) * 100) / 100;

  return rounded;
}

import { applyThousandSeparator, toRoundFixed } from "./index";

/** 数字格式化选项。 */
export type NumberFormationProps = {
  /**
   * @description 格式化语言；默认使用 en-US
   */
  language?: "zh-CN" | "en-US" | string;

  /**
   * @description 是否自动进行 K、M、B 或 万、亿单位换算
   */
  autoFormat?: boolean;

  /**
   * @description 自动换算时的最小整数位数
   */
  formatScale?: number;

  /**
   * @description 保留的小数位数
   */
  decimalScale?: number;

  /**
   * @description 是否使用千分位分隔符，也可以传入自定义分隔符
   */
  thousandSeparator?: boolean | string;

  /**
   * @description 数字前缀
   */
  prefix?: string;

  /**
   * @description 数字后缀
   */
  suffix?: string;

  /**
   * @description 小数部分为 0 时是否隐藏末尾的 0
   */
  hiddenZero?: boolean;
};

/** 已拆分的数字格式化结果，适合需要分别渲染整数、小数和单位的场景。 */
export type Formation = {
  minus?: string;
  intNumStr: string;
  floatNum: string;
  prefix?: string;
  suffix?: string;
  unit?: string;
};

/** 根据配置拆分数字的符号、整数、小数、单位、前缀和后缀。 */
export function formation(
  value: number,
  options: NumberFormationProps = {}
): Formation {
  const {
    autoFormat = true,
    thousandSeparator = true,
    hiddenZero = true,
    prefix = "",
    suffix = "",
    formatScale = 4,
    decimalScale = 2,
    language = "en-US",
  } = options;

  if (!Number.isFinite(value)) {
    return { minus: "", prefix, intNumStr: "", floatNum: "", unit: "", suffix };
  }

  const minus = value < 0 ? "-" : "";
  const _value = Math.abs(value);

  const valueStr = toRoundFixed(_value, decimalScale).toString();
  const intVal = valueStr.split(".")[0] ?? "0";

  let unit = "";
  let newValue = toRoundFixed(_value, decimalScale);

  if (language === "zh-CN") {
    if (autoFormat && intVal) {
      if (intVal.length >= formatScale + 4) {
        unit = "亿";
        newValue = toRoundFixed(newValue / 100000000, decimalScale);
      } else if (intVal.length >= formatScale) {
        unit = "万";
        newValue = toRoundFixed(newValue / 10000, decimalScale);
      }
    }
  } else {
    if (autoFormat && intVal) {
      if (intVal.length >= formatScale + 6) {
        unit = "B";
        newValue = toRoundFixed(_value / 1000000000, decimalScale);
      } else if (intVal.length >= formatScale + 3) {
        unit = "M";
        newValue = toRoundFixed(_value / 1000000, decimalScale);
      } else if (intVal.length >= formatScale) {
        unit = "K";
        newValue = toRoundFixed(_value / 1000, decimalScale);
      }
    }
  }

  const arrValue = newValue.toString().split(".");
  const intNum = arrValue[0] || "";
  let floatNum = arrValue[1] || "";
  const intNumStr = applyThousandSeparator(intNum, thousandSeparator);
  // 补零
  if (!hiddenZero && !floatNum) {
    floatNum = new Array(decimalScale).fill(0).join("");
  }

  return {
    minus,
    prefix,
    intNumStr,
    floatNum,
    unit,
    suffix,
  };
}

/** 将数字格式化为可直接展示的字符串。默认使用 en-US 和自动单位换算。 */
export function formatNumber(
  value: number,
  options?: NumberFormationProps
): string {
  const { minus, prefix, intNumStr, floatNum, unit, suffix } = formation(
    value,
    options
  );
  const floatNumStr = floatNum ? `.${floatNum}` : "";
  return `${minus}${prefix}${intNumStr}${floatNumStr}${unit}${suffix}`;
}

/** 将带有英文单位的数字还原为原始数值。 */
export function unFormatNumber(
  value: number,
  unit: "K" | "M" | "G" | "T" | string
): number {
  switch (unit) {
    case "K":
      return value * 1000;
    case "M":
      return value * 1000000;
    case "G":
    case "B":
      return value * 1000000000;
    case "T":
      return value * 1000000000000;
    default:
      return value;
  }
}
